import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"32、【恒】 巽下震上","description":"周易集注 - 32、【恒】 巽下震上","frontmatter":{"title":"32、【恒】 巽下震上","description":"周易集注 - 32、【恒】 巽下震上"},"headers":[],"relativePath":"zh/classics/jizhu/036.md","filePath":"zh/classics/jizhu/036.md"}'),l={name:"zh/classics/jizhu/036.md"};function h(t,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_32、【恒】-巽下震上" tabindex="-1">32、【恒】 巽下震上 <a class="header-anchor" href="#_32、【恒】-巽下震上" aria-label="Permalink to “32、【恒】 巽下震上”">​</a></h1><p>恒，久也。男在女上，男动乎外，女顺乎内，人理之常，故曰恒。又见彖辞，皆恒之义也。《序卦》：“夫妇之道，不可以不久也，故受之恒。”言夫妇偕老，终身不变者也。盖咸少男在少女之下，以男下女，乃男女交感之义;恒，长男在长女之上，男尊女卑，乃夫妇居室之常。论交感之情，则少为亲切，论尊卑之序，则长当谨严，所以次哉。</p><p>恒之道，可以亨通。恒而能亨，乃无咎也。恒而不可以亨，非可恒之道也，为有咎矣。如君子恒于善，故无咎;小人恒于恶，焉得无咎。然恒亨而后无咎，何也?盖恒必利于正，若不正，岂能恒?如孝，置之而塞乎天地，溥之而横乎四海，如此正，方得恒，故利贞。恒必利有攸往，达之家邦，万古不穷，如孝施之后世而无朝夕，方谓之恒，如不可攸往，不谓之恒矣。利贞，不易之恒也。恒之利者也，利有攸往，不已之恒也，亦恒之利者也，故恒必两利。〔恒字《广韵.玉篇》皆有下一画，独《易经》无下一画，与无字同，不同各经无字。〕</p><p>《彖》曰：恒，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。恒，亨无咎，利贞，久于其道也。天地之道，恒久而不已也。利有攸往，终则有始也。日月得天而能久照，四时变化而能久成，圣人久于其道而天下化成。观其所恒，而天地万物之情可见矣!</p><p>释卦字义。又以卦综卦象卦德释卦名卦辞而极言之恒者长久也。若以恒字论，左旁从立心，右旁从一日，言立心如一日，久而不变者也。刚上而柔下者，本卦综咸。刚上者，咸下卦之艮上而为恒之雷*也，柔下者，咸上卦之兑，下而为恒之巽也。阴阳之理，刚上柔下，分之常。迅雷烈风，交助其势，气之常。男动作于外，女巽顺于内，人理之常。刚以应柔，柔以应刚，交感之常。此四者，皆理之常，故曰恒。恒亨无咎利贞者，以久于其道也，盖道者，天下古今共由之路，天地之正道也。惟久于其道，故亨，故无咎，故利贞。若非其道，亦不能恒矣。且恒久莫过于天地，天地之道，恒久而不已者也。惟其恒久不已，所以攸往不穷。盖凡事之攸往，至于终而不能恒久者，以其终而不能又始也。终而不能始，则自终而止，有止息间断非恒久不已者矣，安能攸往。惟天地之道，昼终矣矣，而又有夜之始;夜之终矣，而又有昼之始;寒终矣，而有暑之始;暑之终矣，而又有寒之始。终则有始，循环无端，此天地所以恒久也。此恒所以必利有攸往，而后谓之恒也。若有所往，不能终始循环不穷，则与天地不相似，安得谓之恒哉。得天者，附丽于天也。变化者，寒而暑，暑而寒，迭相竭还相本，阴变于阳，阳化为阴也。久成者，成其岁功也，久于其道者，仁渐义摩也。化成者，化之而成其美俗也。此极言恒久之道，言观其所恒，可见万古此天地，万古此恒也。万古此万物，万古此恒也。若当春时为夏，当秋时为冬，当生物时不生，当成物时不成，此之谓变怪，安得谓之恒。</p><ul><li>雷或作震。</li></ul><h3 id="《象》曰-雷风恒-君子以立不易方。" tabindex="-1">《象》曰：雷风恒，君子以立不易方。 <a class="header-anchor" href="#《象》曰-雷风恒-君子以立不易方。" aria-label="Permalink to “《象》曰：雷风恒，君子以立不易方。”">​</a></h3><p>立者，正于此而不迁也。方者，大中至正之理，理之不可易者也。如为人君止于仁，为人臣止于敬是也。不易方者，非胶于一定也。理在于此，则止而不迁。如冬之寒，理在于衣裘，则衣裘而不易其葛;夏之暑，理在于衣葛，则衣葛而不易其裘是也。巽性入，入而在内;震性动，出而在外。二物各居其位，不易方之象也，故曰不易方。</p><p>初六，浚恒，贞凶，无攸利。</p><p>浚，深也，浚井之浚。浚字生于巽性入之入字来。初六为长女之主，九四为长男之主，乃夫妇也。巽性入，始与夫交之时，即深求以夫妇之常道。四动而决躁，安能始交之时即能从其所求。贞者，初与四为正应，所求非不正也。凶者骤而求之深，彼此必不相契合也，无攸利者，有所往则夫妇反目矣。盖初阴居阳位，四阳居阴位，夫妇皆不正，皆有气质之性，所以此爻不善。下三爻皆以妻言，初爻凶者，妻求夫之深而凶也。三贞吝者，妻改节而见黜也。上三爻皆以夫言，四无禽者，夫失其刚，而无中馈之具也。五凶者，夫顺从其妻而凶也。</p><p>初与四为正应，妇责备夫以夫妇之常道，亦人情之所有者。然必夫妇居室之久，情事孚契，而后可以深求其常道也。但巽性务入，方交四之始，即深以夫妇之常道求之，则彼此之情未免乖矣，故有浚恒之象。占者如此，则虽贞亦凶，而无攸利也。</p><h3 id="《象》曰-浚恒之凶-始求深也。" tabindex="-1">《象》曰：浚恒之凶，始求深也。 <a class="header-anchor" href="#《象》曰-浚恒之凶-始求深也。" aria-label="Permalink to “《象》曰：浚恒之凶，始求深也。”">​</a></h3><p>求者，中馈之酒浆器皿，衣服首饰之类也。</p><p>九二，悔亡。</p><p>以阳居阴，本有悔矣，以其久中，故其悔亡。亡者失之于初，而改之于终也。</p><h3 id="《象》曰-九二悔亡-能久中也。" tabindex="-1">《象》曰：九二悔亡，能久中也。 <a class="header-anchor" href="#《象》曰-九二悔亡-能久中也。" aria-label="Permalink to “《象》曰：九二悔亡，能久中也。”">​</a></h3><p>可久之道中焉止矣，人能恒久于中，岂止悔亡。孔子之言，盖就周公之爻辞而美之也。</p><p>九三，不恒其德，或承之羞，贞吝。</p><p>阳德居正，故得称德，不恒其德者，改节也。居巽之极，为进退，为不果，改节之象也。又变坎为狐疑，此心不定，亦改节之象也。长女为长男之妇，不恒其德而改节，则失其为妇之职矣。既失其职，则夫不能容，而妇被黜矣。或者外人也，承者进也，羞者致滋味也。变坎有饮食之象，羞之象也。因妇见黜，外人与夫进其羞也。贞者，九三位正也。若依旧注，羞作羞耻，则下吝字重言羞矣。</p><p>九三位虽得正，然过刚不中，当雷风交接之际，雷动而风从，不能自守，故有不恒其德，或承之羞之象。虽正亦可羞矣，故戒占者如此。</p><h3 id="《象》曰-不恒其德-无所容也。" tabindex="-1">《象》曰：不恒其德，无所容也。 <a class="header-anchor" href="#《象》曰-不恒其德-无所容也。" aria-label="Permalink to “《象》曰：不恒其德，无所容也。”">​</a></h3><p>无所容者，夫不能容其妇，而见黜也，所以使外人进其羞也。</p><p>九四，田无禽。</p><p>应爻为地道，又震为大涂，故曰田，与师卦田有禽之田同。本卦之大象，与师卦之大象，皆与小过卦同，故皆曰禽。应爻巽为鹳，亦禽之象也。应爻深入，与井下卦同巽，故皆曰无禽也。师卦所应刚实，故有禽。本卦所应阴虚，故无禽。</p><p>九四以阳居阴，久非其位，且应爻深入，故有田无禽之象。既无禽，则不能与妻备其中馈之具，夫非其夫矣，故其象占如此。</p><h3 id="《象》曰-久非其位-安得禽也。" tabindex="-1">《象》曰：久非其位，安得禽也。 <a class="header-anchor" href="#《象》曰-久非其位-安得禽也。" aria-label="Permalink to “《象》曰：久非其位，安得禽也。”">​</a></h3><p>久非其位，则非所久而久矣，故不得禽。</p><p>六五，恒其德贞，妇人吉，夫子凶。</p><p>丈夫用刚用柔，各适其宜，以柔顺为常，是因人成事矣，所以凶。此爻变兑，兑为少女，又为妾，妇人之象也。妇人以顺为正，故吉。</p><p>六五恒其中德正矣，故有恒其德贞之象。但刚而中，可恒也。柔而中，妇人之常，非夫子之所当常也，故占者有吉有凶又如此。</p><h3 id="《象》曰-妇人贞吉-从一而终也。夫子制义-从妇凶也。" tabindex="-1">《象》曰：妇人贞吉，从一而终也。夫子制义，从妇凶也。 <a class="header-anchor" href="#《象》曰-妇人贞吉-从一而终也。夫子制义-从妇凶也。" aria-label="Permalink to “《象》曰：妇人贞吉，从一而终也。夫子制义，从妇凶也。”">​</a></h3><p>从一者从夫也，妇人无专制之义，惟在从夫，顺从乃其宜也。制者裁制也。从妇者，从妇人顺从之道也。夫子刚果独断，以义制事，若如妇人之顺从，委靡甚矣，岂其所宜，故凶。</p><p>上六，振恒，凶。振去声</p><p>振者奋也，举也，整也。振恒者，振动其恒也。如宋时，祖宗本有恒久法度，王安石以祖宗不足法，乃纷更旧制，正所谓振恒也。凶者，不惟不能成事，而反愤事也。在下入，乃巽之性，浚恒也。在上动，乃震之性，振恒也。方恒之始，不可浚而乃浚，既恒之终，不可振而乃振，故两爻皆凶。</p><p>上六阴柔，本不能固守其恒者也，且居恒之极，处震之终，恒极则反常，震终则过动，故有振恒之象。占者之凶可知矣。</p><h3 id="《象》曰-振恒在上-大无功也。" tabindex="-1">《象》曰：振恒在上，大无功也。 <a class="header-anchor" href="#《象》曰-振恒在上-大无功也。" aria-label="Permalink to “《象》曰：振恒在上，大无功也。”">​</a></h3><p>大无功者，不惟无功，而大无功也。曰大者，上而无益于国家，而下不利于生民，安石靖康之祸是也。</p>',37)])])}const f=e(l,[["render",h]]);export{_ as __pageData,f as default};
